function renderStats(n){const vc=C.filter(c=>c.vis),tot=R.length*vc.length,fl=R.reduce((a,r)=>a+vc.filter(c=>isImg(c)?r.img:String(val(r,c)).trim()).length,0),pc=tot?Math.round(fl/tot*100):0;$('#pgt').textContent=pc+'% of cells filled';$('#pgb').style.width=pc+'%';$('#stats').innerHTML=[['🛒',R.length,'Products'],['📄',n,'Pages'],['🧩',C.filter(c=>c.vis).length,'Columns'],['🖼️',R.filter(r=>r.img).length,'Images'],['💾',`<span id="sto">${STO}</span>`,'Storage']].map(([i,v,l])=>`<div><span>${i}</span><b>${v}</b><small>${l}</small></div>`).join('')}
