$('#tabs').onclick=e=>{const x=e.target.closest('[data-x]'),cs0=[...document.querySelectorAll('main .card')];if(x)return cs0.forEach(c=>c.open=x.dataset.x=='1');const b=e.target.closest('[data-j]');if(!b)return;const cs=cs0,t=cs.find(c=>c.querySelector('summary').textContent.includes(b.dataset.j));if(!t)return;cs.forEach(c=>c.open=c==t);$('#tabs').querySelectorAll('button').forEach(x=>x.classList.toggle('on',x==b));t.scrollIntoView({behavior:'smooth',block:'start'})};
$('#bk').onclick=()=>{const f=document.createElement('input');f.type='file';f.accept=IMG_ACCEPT;f.multiple=true;f.onchange=async()=>{const fs=[...f.files];let n=0,bad=0;for(const file of fs){try{const im=await loadIm(await readImg(file));let r=R.find(r=>!r.img);if(!r){r=mk();R.push(r)}const k=Math.min(1,1200/im.width),x=document.createElement('canvas');x.width=Math.round(im.width*k);x.height=Math.round(im.height*k);x.getContext('2d').drawImage(im,0,0,x.width,x.height);const t=trimC(x);r.img=t.url;r.ar=t.ar;n++}catch(e){bad++}}if(n){renderTable();draw()}toast(n?`Added ${n} image${n>1?'s':''} to rows, in order${bad?` · ${bad} file${bad>1?'s':''} could not be read`:''}`:'None of those files could be read as images.')};f.click()};
const AS=new Map(),AI=[],aref=v=>{let k=AS.get(v);if(k==null){k=AI.length;AI.push(v);AS.set(v,k)}return '\u0001'+k};let HS=[],hx=-1,rs=false;
function snap(){const j=JSON.stringify(proj(),(k,v)=>(k=='img'||k=='logo'||k=='photo'||k=='wm'||k=='wmRaw')&&typeof v=='string'?aref(v):v);if(rs){rs=false;HS[hx]=j;return}if(HS[hx]===j)return;HS=HS.slice(0,hx+1);HS.push(j);if(HS.length>40)HS.shift();hx=HS.length-1}
function goto(i){if(i<0||i>=HS.length)return toast(i<0?'Nothing to undo.':'Nothing to redo.');const w=hx;hx=i;rs=true;try{apply(JSON.parse(HS[i],(k,v)=>typeof v=='string'&&v[0]=='\u0001'?AI[+v.slice(1)]:v));toast(i<w?'Undone':'Redone')}catch(e){rs=false}}
addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey))return;const k=e.key.toLowerCase(),f=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(k=='s'){e.preventDefault();K.save()}else if(!f&&k=='z'){e.preventDefault();goto(e.shiftKey?hx+1:hx-1)}else if(!f&&k=='y'){e.preventDefault();goto(hx+1)}});
