async function tplDlg(){const r=await dlg('Templates',`<p style="margin:0;color:var(--mut)">Start from a ready-made price list. Your current pamphlet will be replaced.</p><div class="tpg">${TPL.map((t,i)=>`<button class="tpc" data-i="${i+10}"><span>${t.i}</span><b>${t.n}</b><small>${t.r?t.r.length+' sample products':'one empty row'}</small></button>`).join('')}</div>`,['Cancel']);if(r.i<10)return;const t=TPL[r.i-10];pushDoc({id:uid(),name:t.n,C:DC(),R:t.r?t.r.map(a=>mk(...a)):[mk()],T:{...DS(),title:t.t,...(t.h?{layout:'h',page:'A5L'}:{})},hs:[],hx:-1});toast('Template opened in a new tab')}
function helpDlg(){return dlg('Help & Shortcuts',`<div class="sx"><h4>Quick start</h4><p style="margin:0">1. Add products and images → 2. Style fonts, colours and header → 3. Download as PNG, JPG, JPEG, WebP, PDF or PPT, or print.</p></div><div class="sx"><h4>Shortcuts</h4><p style="margin:0"><b>Ctrl+Z</b> undo · <b>Ctrl+Y</b> redo · <b>Ctrl+S</b> save project · <b>Arrow keys</b> move between cells (Ctrl+Arrow jumps to the edge) · <b>Ctrl+D</b> fill down · paste cells copied from Excel / Google Sheets · <b>Enter</b> next row · <b>Shift+Enter</b> previous row · in Product Name, <b>Enter</b> adds a new line and <b>Ctrl+Enter</b> moves to the next row</p></div><div class="sx"><h4>Tips</h4><p style="margin:0">Product images accept JPG, JPEG, PNG, WebP, GIF, BMP, SVG, AVIF, TIFF, HEIC and DICOM (.dcm). Use <b>Bulk add images</b> to fill many rows at once, <b>Sort rows</b> to order by price or weight, and <b>Close editor</b> for a full-page preview. Your work is saved in this browser automatically.</p></div>`,['Got it'])}
